import { pathToFileURL } from 'node:url';
import { expect, test } from '@playwright/test';
import { trackRequests } from './helpers';

// Checks a page generated by the Lean side (`proofmap build`), given by PROOFMAP_PAGE: it shows
// the app with data, offline. Optional PROOFMAP_ROOT names a root
// declaration that must be listed and searchable.
const page_ = process.env.PROOFMAP_PAGE;
const root = process.env.PROOFMAP_ROOT;

test.skip(!page_, 'set PROOFMAP_PAGE to a generated proofmap.html');

test('generated page opens offline with its data', async ({ page, context }) => {
  await context.route(/^(?!file:|data:|blob:).*/, (r) => r.abort());
  const external = trackRequests(page);
  const errors: string[] = [];
  page.on('pageerror', (e) => errors.push(e.message));
  await page.goto(pathToFileURL(page_!).href);
  await expect(page.getByRole('heading', { level: 1 })).not.toBeEmpty();
  await expect(page.locator('.card').first()).toBeVisible();
  if (root) {
    await page.keyboard.press('/');
    await page.keyboard.type(root.split('.').pop()!);
    await page.keyboard.press('Enter');
    await expect(page.getByRole('complementary', { name: 'Details' })).toContainText(root);
  }
  expect(external).toEqual([]);
  expect(errors).toEqual([]);
});
